```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, CASE WHEN duration < 1000000 THEN '<1ms' WHEN duration < 1000000000 THEN '1ms-1s' ELSE '>=1s' END AS bucket, count(*) AS n FROM abnormal_traces WHERE service_name = 'search' AND span_name = 'rate.Rate/GetRates' GROUP BY 1, 2 ORDER BY 1, 2",
          "claim": "Of about 364 search→rate calls, 359 errored in under 1 ms; almost none waited on a connection timeout."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, count(*) AS rate_server_spans FROM normal_traces WHERE service_name = 'rate' AND attr_span_kind = 'Server' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name = 'rate' AND attr_span_kind = 'Server'",
          "claim": "Rate's server spans collapse from about 1065 in the normal window to 1 or 2 in the incident window."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, count(*) AS samples, round(min(value),1) AS min_uptime_s, round(max(value),1) AS max_uptime_s FROM abnormal_metrics_sum WHERE metric = 'k8s.pod.uptime' AND attr_k8s_pod_name LIKE 'rate-%' GROUP BY 1",
          "claim": "Rate's pod uptime rises continuously with no reset, so the rate pod never restarted or went away."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE (service_name = 'frontend' AND span_name = 'HTTP /hotels') OR (service_name = 'frontend' AND span_name = 'search.Search/Nearby') GROUP BY ALL ORDER BY 1, 2, 3",
          "claim": "All 301 frontend /hotels requests returned HTTP 500 while frontend's calls to search.Search/Nearby errored."
        }
      ]
    }
  ]
}
```

